package vn.nanase.hako;
import android.content.*;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.util.AtomicFile;
import java.io.*;
import java.util.*;
import java.util.zip.*;
import org.json.*;

/** Explicit portable backup. No picker, startup scan or exported web-login cookies. */
public final class DataTransfer {
 public static File folder(Context c)throws IOException{File base=c.getExternalFilesDir(null);if(base==null)throw new IOException("Không tìm thấy bộ nhớ dùng để chuyển dữ liệu");File dir=new File(base,"transfer");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException("Không tạo được thư mục chuyển dữ liệu");return dir;}
 public static File archive(Context c)throws IOException{return new File(folder(c),"Hako-transfer.zip");}
 private static JSONObject preferences(Context c)throws Exception{JSONObject root=new JSONObject();for(String name:new String[]{"settings","read_queue","download_resume","diagnostics"}){JSONObject values=new JSONObject();for(Map.Entry<String,?> entry:c.getSharedPreferences(name,0).getAll().entrySet()){String key=entry.getKey();if(name.equals("diagnostics")&&!Arrays.asList("endpoint","token","bundled_config_v1").contains(key))continue;Object v=entry.getValue();String type=v instanceof Set?"set":v instanceof Integer?"int":v instanceof Long?"long":v instanceof Float?"float":v instanceof Boolean?"boolean":"string";values.put(key,new JSONObject().put("type",type).put("value",v instanceof Set?new JSONArray((Set<?>)v):v));}root.put(name,values);}return root;}
 private static void put(ZipOutputStream zip,String name,byte[] data)throws IOException{zip.putNextEntry(new ZipEntry(name));zip.write(data);zip.closeEntry();}
 private static void put(ZipOutputStream zip,String name,File file)throws IOException{ZipEntry entry=new ZipEntry(name);entry.setTime(file.lastModified());zip.putNextEntry(entry);try(InputStream in=new FileInputStream(file)){copy(in,zip);}zip.closeEntry();}
 private static void tree(ZipOutputStream zip,String prefix,File dir)throws IOException{File[] files=dir.listFiles();if(files==null)return;for(File file:files){String name=prefix+file.getName();if(file.isDirectory())tree(zip,name+"/",file);else if(!file.getName().endsWith(".tmp")&&!file.getName().endsWith(".bak")&&!file.getName().endsWith(".new"))put(zip,name,file);}}
 private static void copy(InputStream in,OutputStream out)throws IOException{byte[] buffer=new byte[32768];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}
 public static File export(Context c,boolean content)throws Exception{
  if(Repository.busy.get())throw new IOException("Hãy đợi lượt cập nhật/tải hiện tại kết thúc hoặc tạm dừng trước khi sao lưu");Store store=Store.get(c);AtomicFile target=new AtomicFile(archive(c));FileOutputStream stream=null;
  synchronized(Repository.class){if(Repository.busy.get())throw new IOException("Hãy đợi lượt tải/cập nhật kết thúc");try{stream=target.startWrite();ZipOutputStream zip=new ZipOutputStream(stream);zip.setLevel(0);put(zip,"manifest.json",new JSONObject().put("format",1).put("package","vn.nanase.hako").put("contents",content).put("createdAt",System.currentTimeMillis()).toString().getBytes("UTF-8"));
    synchronized(store){SQLiteDatabase db=store.getWritableDatabase();Store.traceQuery("PRAGMA wal_checkpoint(FULL)");try(Cursor checkpoint=db.rawQuery("PRAGMA wal_checkpoint(FULL)",null)){if(checkpoint.moveToFirst()&&checkpoint.getInt(0)!=0)throw new IOException("Database còn đang ghi, hãy thử lại");}put(zip,"db/hako.db",new File(db.getPath()));put(zip,"preferences.json",preferences(c).toString().getBytes("UTF-8"));}
    if(content)tree(zip,"chapters/",store.cache);for(String dir:new String[]{"story-info","toc-state"})tree(zip,dir+"/",new File(c.getFilesDir(),dir));for(String name:new String[]{"library-state.json","library-delta.json","validation-index.json","reader-font.ttf"}){File file=new File(c.getFilesDir(),name);if(file.isFile())put(zip,name,file);}zip.finish();zip.flush();target.finishWrite(stream);return target.getBaseFile();
  }catch(Exception error){if(stream!=null)target.failWrite(stream);throw error;}}
 }
 private static boolean allowed(String name){if(name.contains("..")||name.contains("\\")||name.startsWith("/"))return false;return Arrays.asList("manifest.json","preferences.json","db/hako.db","library-state.json","library-delta.json","validation-index.json","reader-font.ttf").contains(name)||name.matches("chapters/[a-z0-9-]+/[a-zA-Z0-9._-]+")||name.matches("(story-info|toc-state)/[a-z0-9.-]+");}
 private static void validatePreferences(JSONObject root)throws Exception{
  for(String name:new String[]{"settings","read_queue","download_resume","diagnostics"}){JSONObject values=root.getJSONObject(name);Iterator<String> keys=values.keys();while(keys.hasNext()){String key=keys.next();JSONObject row=values.getJSONObject(key);String type=row.getString("type");Object value=row.get("value");if(Arrays.asList("int","long","float").contains(type)){if(!(value instanceof Number))throw new IOException("Tùy chọn số không hợp lệ");}else if(type.equals("boolean")){if(!(value instanceof Boolean))throw new IOException("Tùy chọn không hợp lệ");}else if(type.equals("string")){if(!(value instanceof String))throw new IOException("Tùy chọn chữ không hợp lệ");}else if(type.equals("set")){if(!(value instanceof JSONArray))throw new IOException("Tùy chọn danh sách không hợp lệ");JSONArray list=(JSONArray)value;for(int i=0;i<list.length();i++)if(!(list.get(i) instanceof String))throw new IOException("Danh sách không hợp lệ");}else throw new IOException("Kiểu tùy chọn không hợp lệ");}}
 }
 private static void restorePreferences(Context c,JSONObject root)throws Exception{for(String name:new String[]{"settings","read_queue","download_resume","diagnostics"}){JSONObject values=root.optJSONObject(name);if(values==null)continue;android.content.SharedPreferences.Editor edit=c.getSharedPreferences(name,0).edit().clear();Iterator<String> keys=values.keys();while(keys.hasNext()){String key=keys.next();JSONObject row=values.getJSONObject(key);String type=row.getString("type");Object value=row.get("value");switch(type){case "int":edit.putInt(key,((Number)value).intValue());break;case "long":edit.putLong(key,((Number)value).longValue());break;case "float":edit.putFloat(key,((Number)value).floatValue());break;case "boolean":edit.putBoolean(key,(Boolean)value);break;case "set":Set<String> set=new HashSet<>();JSONArray list=(JSONArray)value;for(int i=0;i<list.length();i++)set.add(list.getString(i));edit.putStringSet(key,set);break;case "string":edit.putString(key,(String)value);break;default:throw new IOException("Kiểu tùy chọn không hợp lệ");}}if(name.equals("diagnostics"))edit.putBoolean("auto",false);if(!edit.commit())throw new IOException("Không ghi được tùy chọn");}}
 public static void restore(Context c)throws Exception{
  Store store=Store.get(c);if(Repository.busy.get())throw new IOException("Không nhận gói trong lúc tải/cập nhật");if(!store.books().isEmpty())throw new IOException("Chỉ nhận gói trên thiết bị mới chưa có truyện, để không ghi đè dữ liệu hiện có");
  File archive=archive(c),stage=new File(c.getFilesDir(),"transfer-stage-"+UUID.randomUUID());if(!archive.isFile())throw new IOException("Hãy copy Hako-transfer.zip vào: "+folder(c).getAbsolutePath());stage.mkdirs();
  try{long total=0,available=stage.getUsableSpace();int entries=0;try(ZipInputStream zip=new ZipInputStream(new FileInputStream(archive))){ZipEntry entry;while((entry=zip.getNextEntry())!=null){String name=entry.getName();if(entry.isDirectory())continue;if(!allowed(name)||++entries>100000)throw new IOException("Gói có đường dẫn không hợp lệ");File target=new File(stage,name);if(target.exists())throw new IOException("Gói có tệp trùng");target.getParentFile().mkdirs();try(OutputStream out=new FileOutputStream(target)){byte[] buffer=new byte[32768];int n;long size=0;while((n=zip.read(buffer))!=-1){size+=n;total+=n;if(size>1024L*1024*1024||total>available)throw new IOException("Không đủ bộ nhớ hoặc tệp quá lớn");out.write(buffer,0,n);}}if(entry.getTime()>0)target.setLastModified(entry.getTime());}}
   JSONObject manifest=new JSONObject(Store.read(new File(stage,"manifest.json")));if(manifest.optInt("format")!=1||!"vn.nanase.hako".equals(manifest.optString("package")))throw new IOException("Gói không thuộc Hako Pocket");File db=new File(stage,"db/hako.db");if(!db.isFile())throw new IOException("Gói thiếu database");Store.traceQuery("PRAGMA quick_check");try(SQLiteDatabase check=SQLiteDatabase.openDatabase(db.getPath(),null,SQLiteDatabase.OPEN_READONLY);Cursor cursor=check.rawQuery("PRAGMA quick_check",null)){if(!cursor.moveToFirst()||!"ok".equals(cursor.getString(0)))throw new IOException("Database trong gói bị lỗi");Store.traceQuery("PRAGMA user_version");try(Cursor version=check.rawQuery("PRAGMA user_version",null)){if(!version.moveToFirst()||version.getInt(0)!=3)throw new IOException("Phiên bản database không tương thích");}}
   JSONObject pref=new JSONObject(Store.read(new File(stage,"preferences.json")));validatePreferences(pref);
   if(!manifest.getBoolean("contents")){
    try(SQLiteDatabase metadata=SQLiteDatabase.openDatabase(db.getPath(),null,SQLiteDatabase.OPEN_READWRITE)){metadata.execSQL("UPDATE chapters SET ready=0,error='' ");}
    Store.delete(new File(stage,"chapters"));Store.delete(new File(stage,"toc-state"));for(String name:new String[]{"library-state.json","library-delta.json","validation-index.json"})Store.delete(new File(stage,name));
    pref.getJSONObject("settings").put("last_offline_percent",new JSONObject().put("type","int").put("value",0));
   }
   synchronized(Repository.class){if(Repository.busy.get())throw new IOException("Không nhận gói trong lúc tải/cập nhật");synchronized(store){if(!store.books().isEmpty())throw new IOException("Thiết bị đã có truyện; không ghi đè");store.close();File destination=c.getDatabasePath("hako.db");if(!db.renameTo(destination))throw new IOException("Không nhận được database");for(String suffix:new String[]{"-wal","-shm","-journal"})new File(destination.getPath()+suffix).delete();moveFiles(stage,c.getFilesDir(),"");restorePreferences(c,pref);store.resetDerived();}}LibraryState.resetForImport();
  }finally{Store.delete(stage);}
 }
 private static void moveFiles(File stage,File root,String prefix)throws IOException{File[] files=stage.listFiles();if(files==null)return;for(File file:files){String name=prefix+file.getName();if(file.isDirectory())moveFiles(file,root,name+"/");else if(!Arrays.asList("manifest.json","preferences.json","db/hako.db").contains(name)){File target=new File(root,name);target.getParentFile().mkdirs();if(target.exists()&&!target.delete())throw new IOException("Không nhận được tệp dữ liệu");if(!file.renameTo(target))throw new IOException("Không chuyển được tệp dữ liệu");}}}
}

